<?php
defined('ABSPATH') || exit;
class PCE_Approved_Admin {
    static function init() {
        add_action('admin_menu',function(){add_submenu_page('prime-estimator','Approved pricing & business details','Approved pricing','manage_options','prime-approved',[__CLASS__,'page']);});
        add_action('admin_post_pce_approved_save',[__CLASS__,'save']);
        add_action('admin_post_pce_export',[__CLASS__,'export']);
    }
    static function guard($nonce) { if(!current_user_can('manage_options')) wp_die('Not authorised.');check_admin_referer($nonce); }
    static function save() { self::guard('pce_approved_save');update_option(PCE_Approved::OPTION,PCE_Approved::clean(wp_unslash($_POST['approved']??[])));wp_safe_redirect(admin_url('admin.php?page=prime-approved&saved=1'));exit; }
    static function input($name,$value,$type='number') { echo '<input type="'.esc_attr($type).'" name="approved['.esc_attr($name).']" value="'.esc_attr($value??'').'" '.($type==='number'?'min="0" step="0.01"':'').' style="max-width:100%;width:'.($type==='number'?'100':'520').'px">'; }
    static function page() {
        if(!current_user_can('manage_options'))return;$s=PCE_Approved::settings();
        echo '<div class="wrap"><h1>Approved pricing & business details</h1><p>November 10 proposal. Blank prices mean unavailable, never zero. Enter only client-approved information. Legacy settings and historical enquiries remain unchanged.</p>';
        if(isset($_GET['saved']))echo '<div class="notice notice-success"><p>Saved.</p></div>';
        echo '<p><a class="button" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=pce_export'),'pce_export')).'">Export enquiries CSV</a></p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="pce_approved_save">';wp_nonce_field('pce_approved_save');
        foreach(['lease'=>'End of Lease','regular'=>'Regular'] as $key=>$label) { echo '<h2>'.esc_html($label).' — bedroom × bathroom base rates (AUD)</h2><table class="widefat" style="max-width:720px"><thead><tr><th>Property</th>';for($a=1;$a<=4;$a++)echo '<th>'.$a.' bathroom'.($a>1?'s':'').'</th>';echo '</tr></thead><tbody>';for($b=0;$b<=5;$b++){echo '<tr><th>'.($b?$b.' bedrooms':'Studio').'</th>';for($a=1;$a<=4;$a++){echo '<td><label><span class="screen-reader-text">'.esc_html($label)." $b bedrooms, $a bathrooms</span>";self::input("grids][$key][$b:$a",$s['grids'][$key]["$b:$a"]??null);echo '</label></td>';}echo '</tr>';}echo '</tbody></table>'; }
        echo '<h2>Add-ons and carpet rates (AUD)</h2><table class="form-table">';
        foreach(['extras'=>PCE_Approved::EXTRAS,'carpets'=>PCE_Approved::CARPETS] as $group=>$labels) foreach($labels as $k=>$label){echo '<tr><th>'.esc_html(($group==='carpets'?'Carpet — ':'').$label).'</th><td>';self::input("$group][$k",$s[$group][$k]);echo '</td></tr>';}
        foreach(['deep_multiplier'=>'Deep/Spring multiplier','storey_percent'=>'Double-storey surcharge (%)','recurring_percent'=>'Weekly / fortnightly discount (%)','travel_fee'=>'Zone 2 fee per visit (AUD)','minimum'=>'Minimum charge (AUD)'] as $key=>$label){echo '<tr><th>'.esc_html($label).'</th><td>';self::input($key,$s[$key]);echo '</td></tr>';}echo '</table><h2>Approved suburb list</h2><p>One per line: Suburb | Postcode | Zone (1 = 0–15 km; 2 = 15–25 km). Only listed suburbs receive estimates.</p><textarea name="approved[suburbs]" rows="10" cols="80">';foreach($s['suburbs'] as $r)echo esc_textarea($r['name'].' | '.$r['postcode'].' | '.$r['zone']."\n");echo '</textarea><h2>Approved business details</h2><p>Use an approved business-domain sender with configured SMTP. Empty contact actions are visibly unavailable.</p><table class="form-table">';
        foreach(['phone'=>'Phone (including country code)','whatsapp'=>'WhatsApp (international digits)','email'=>'Business email / owner notification','owner_email'=>'Additional owner Gmail notification','sender_email'=>'Business-domain From email','abn'=>'ABN','reviews_url'=>'Google reviews URL','response_notice'=>'Response-time notice','discount_message'=>'Recurring-discount message'] as $k=>$label){echo '<tr><th>'.esc_html($label).'</th><td>';self::input($k,$s[$k],str_contains($k,'email')?'email':'text');echo '</td></tr>';}echo '</table>';submit_button('Save approved details');echo '</form></div>';
    }
    static function detail($row,$quote) {
        echo '<p><a href="'.esc_url(admin_url('admin.php?page=prime-estimator')).'">← All enquiries</a></p><h2>'.esc_html(PCE_Approved::reference($row['id'])).'</h2><table class="widefat">';
        foreach(['customer_name'=>'Name','customer_phone'=>'Phone','customer_email'=>'Email','suburb'=>'Suburb','preferred_date'=>'Requested date','notes'=>'Notes','email_error'=>'Email status'] as $key=>$label)echo '<tr><th>'.esc_html($label).'</th><td>'.esc_html($row[$key]??'').'</td></tr>';
        echo '</table><p>Status <select class="pce-status-dropdown" data-id="'.esc_attr($row['id']).'">';foreach(['new','contacted','won','lost','quoted','closed'] as $st)echo '<option value="'.$st.'" '.selected($row['status'],$st,false).'>'.ucfirst($st).'</option>';echo '</select></p><h3>Frozen estimate</h3><p>'.esc_html(self::amount($row)).'</p><table class="widefat">';foreach($quote['lines']??[] as $line)echo '<tr><th>'.esc_html($line['label']).'</th><td>AUD '.esc_html(number_format($line['amount'],2)).'</td></tr>';echo '</table><h3>Saved property and enquiry fields</h3><pre style="white-space:pre-wrap">'.esc_html(wp_json_encode(json_decode($row['property_details'],true),JSON_PRETTY_PRINT)).'</pre><p>Prices are frozen. Mail success means accepted by the configured transport, not confirmed inbox delivery.</p>';
    }
    static function amount($row) { $q=json_decode($row['estimate_breakdown'],true);if(($q['version']??0)===2)return $q['state']==='estimate'?'AUD '.$q['low'].'–'.$q['high']:'Custom quote required';return 'AUD '.number_format((float)$row['total_amount'],2); }
    static function export() {
        self::guard('pce_export');nocache_headers();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="prime-enquiries.csv"');$out=fopen('php://output','w');
        fputcsv($out,['Reference','Received','Status','Name','Email','Phone','Suburb','Service','Estimate','Requested date','Notes','Property / optional fields','Frozen snapshot'],',','"','');
        $offset=0;do { $rows=PCE_DB::get_enquiries(['limit'=>200,'offset'=>$offset]);foreach($rows as $r){$data=[PCE_Approved::reference($r['id']),$r['created_at'],$r['status'],$r['customer_name'],$r['customer_email'],$r['customer_phone'],$r['suburb'],$r['service_type'],self::amount($r),$r['preferred_date'],$r['notes'],$r['property_details'],$r['estimate_breakdown']];$data=array_map(function($v){$v=(string)$v;return preg_match('/^[\s]*[=+@-]/',$v)?"'".$v:$v;},$data);fputcsv($out,$data,',','"','');}$offset+=200;}while(count($rows)===200);fclose($out);exit;
    }
}
